def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple] = []
    rejected: list[int] = []

    def amount(token: str) -> int | None:
        if not token or any(c < "0" or c > "9" for c in token):
            return None
        return int(token)

    for index, op in enumerate(ops):
        parts = op.split(" ")
        verb = parts[0] if parts else ""
        ok = False

        if verb == "open" and len(parts) == 3:
            name, value = parts[1], amount(parts[2])
            if value is not None and value >= 0 and name not in balances:
                balances[name] = value
                history.append(("open", name))
                ok = True
        elif verb == "deposit" and len(parts) == 3:
            name, value = parts[1], amount(parts[2])
            if value is not None and value > 0 and name in balances:
                balances[name] += value
                history.append(("deposit", name, value))
                ok = True
        elif verb == "withdraw" and len(parts) == 3:
            name, value = parts[1], amount(parts[2])
            if (
                value is not None
                and value > 0
                and name in balances
                and name not in frozen
                and balances[name] >= value
            ):
                balances[name] -= value
                history.append(("withdraw", name, value))
                ok = True
        elif verb == "transfer" and len(parts) == 4:
            source, dest, value = parts[1], parts[2], amount(parts[3])
            if (
                value is not None
                and value > 0
                and source != dest
                and source in balances
                and dest in balances
                and source not in frozen
                and balances[source] >= value
            ):
                balances[source] -= value
                balances[dest] += value
                history.append(("transfer", source, dest, value))
                ok = True
        elif verb == "freeze" and len(parts) == 2:
            name = parts[1]
            if name in balances and name not in frozen:
                frozen.add(name)
                history.append(("freeze", name))
                ok = True
        elif verb == "unfreeze" and len(parts) == 2:
            name = parts[1]
            if name in balances and name in frozen:
                frozen.remove(name)
                history.append(("unfreeze", name))
                ok = True
        elif verb == "undo" and len(parts) == 1 and history:
            kind, *args = history.pop()
            if kind == "open":
                del balances[args[0]]
                frozen.discard(args[0])
            elif kind == "deposit":
                balances[args[0]] -= args[1]
            elif kind == "withdraw":
                balances[args[0]] += args[1]
            elif kind == "transfer":
                balances[args[0]] += args[2]
                balances[args[1]] -= args[2]
            elif kind == "freeze":
                frozen.remove(args[0])
            elif kind == "unfreeze":
                frozen.add(args[0])
            ok = True

        if not ok:
            rejected.append(index)

    return balances, rejected
